-- Dimensional Miner • PostgreSQL baseline • application invariants required.
-- UUIDs generated by application. UTC timestamps. Not a complete production migration.
BEGIN;
CREATE TABLE players (
 player_id uuid PRIMARY KEY, username text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','QUARANTINED','BANNED'))
);
CREATE TABLE nodes (
 node_id text PRIMARY KEY, role text NOT NULL CHECK(role IN ('MAIN','INSTANCE','PROXY','WORKSPACE')),
 status text NOT NULL CHECK(status IN ('READY','DRAINING','OFFLINE')), heartbeat_at timestamptz NOT NULL,
 capacity jsonb NOT NULL DEFAULT '{}'
);
CREATE TABLE player_sessions (
 player_id uuid PRIMARY KEY REFERENCES players, node_id text REFERENCES nodes, epoch bigint NOT NULL CHECK(epoch>0),
 state text NOT NULL CHECK(state IN ('ACTIVE','FROZEN','TRANSFERRING','OFFLINE')),
 lease_until timestamptz NOT NULL, snapshot_version bigint NOT NULL DEFAULT 0
);
CREATE TABLE operations (
 operation_id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES players, idempotency_key text NOT NULL,
 request_hash text NOT NULL, command_type text NOT NULL, state text NOT NULL CHECK(state IN ('PENDING','SUCCEEDED','REJECTED')),
 response jsonb, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz,
 UNIQUE(actor_id,idempotency_key)
);
CREATE TABLE content_definitions (
 definition_id text NOT NULL, version integer NOT NULL CHECK(version>0), kind text NOT NULL,
 payload jsonb NOT NULL, checksum text NOT NULL, published_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(definition_id,version)
);
CREATE TABLE accounts (
 account_id uuid PRIMARY KEY, owner_id uuid REFERENCES players, system_code text,
 currency text NOT NULL CHECK(currency IN ('COIN','ENERGY','SERVER_XP')),
 balance bigint NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 0,
 CHECK((owner_id IS NULL) <> (system_code IS NULL)), CHECK(owner_id IS NULL OR balance>=0),
 UNIQUE(owner_id,currency), UNIQUE(system_code,currency)
);
CREATE TABLE ledger_entries (
 entry_id uuid PRIMARY KEY, operation_id uuid NOT NULL REFERENCES operations,
 account_id uuid NOT NULL REFERENCES accounts, delta bigint NOT NULL CHECK(delta<>0),
 reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ledger_account_time ON ledger_entries(account_id,created_at);
CREATE TABLE reward_grants (
 grant_id uuid PRIMARY KEY, player_id uuid NOT NULL REFERENCES players, source_key text NOT NULL UNIQUE,
 payload jsonb NOT NULL, state text NOT NULL CHECK(state IN ('AVAILABLE','CLAIMED','QUARANTINED')),
 created_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz,
 claim_operation_id uuid REFERENCES operations,
 CHECK((state='CLAIMED')=(claimed_at IS NOT NULL))
);
CREATE INDEX mailbox_page ON reward_grants(player_id,created_at,grant_id) WHERE state='AVAILABLE';
CREATE TABLE asset_locations (
 location_id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES players,
 kind text NOT NULL CHECK(kind IN ('INVENTORY','EQUIPPED','STASH','MARKET_ESCROW','JOB_ESCROW','GRANT','DESTROYED')),
 asset_kind text NOT NULL CHECK(asset_kind IN ('ITEM','STACK')),
 container_key text, slot integer, grant_id uuid REFERENCES reward_grants,
 version bigint NOT NULL DEFAULT 0,
 CHECK(slot IS NULL OR slot>=0),
 CHECK((kind IN ('INVENTORY','EQUIPPED','STASH'))=(slot IS NOT NULL)),
 CHECK(slot IS NULL OR container_key IS NOT NULL),
 CHECK((kind='GRANT')=(grant_id IS NOT NULL))
);
CREATE UNIQUE INDEX occupied_slot ON asset_locations(owner_id,container_key,slot) WHERE slot IS NOT NULL;
CREATE TABLE items (
 item_id uuid PRIMARY KEY, location_id uuid NOT NULL UNIQUE REFERENCES asset_locations,
 definition_id text NOT NULL, definition_version integer NOT NULL,
 rarity text NOT NULL, advancement integer NOT NULL DEFAULT 0 CHECK(advancement BETWEEN 0 AND 100),
 refine integer NOT NULL DEFAULT 0 CHECK(refine BETWEEN 0 AND 10),
 engraves jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(engraves)='array' AND jsonb_array_length(engraves)<=3),
 sockets jsonb NOT NULL DEFAULT '[]', binding text NOT NULL CHECK(binding IN ('UNBOUND','ACCOUNT_BOUND')),
 durability integer NOT NULL CHECK(durability>=0), version bigint NOT NULL DEFAULT 0,
 FOREIGN KEY(definition_id,definition_version) REFERENCES content_definitions
);
CREATE TABLE material_stacks (
 stack_id uuid PRIMARY KEY, location_id uuid NOT NULL UNIQUE REFERENCES asset_locations,
 definition_id text NOT NULL, definition_version integer NOT NULL,
 quantity bigint NOT NULL CHECK(quantity>0), binding text NOT NULL CHECK(binding IN ('UNBOUND','ACCOUNT_BOUND')),
 FOREIGN KEY(definition_id,definition_version) REFERENCES content_definitions
);
CREATE TABLE player_unlocks (
 player_id uuid NOT NULL REFERENCES players, unlock_id text NOT NULL, granted_at timestamptz NOT NULL DEFAULT now(),
 source_operation_id uuid REFERENCES operations, PRIMARY KEY(player_id,unlock_id)
);
CREATE TABLE quest_progress (
 player_id uuid NOT NULL REFERENCES players, quest_id text NOT NULL, definition_version integer NOT NULL,
 state text NOT NULL CHECK(state IN ('ACTIVE','COMPLETE','CLAIMED')), progress jsonb NOT NULL DEFAULT '{}',
 version bigint NOT NULL DEFAULT 0, PRIMARY KEY(player_id,quest_id)
);
CREATE TABLE transfers (
 transfer_id uuid PRIMARY KEY, player_id uuid NOT NULL REFERENCES players, source_node text NOT NULL REFERENCES nodes,
 destination_node text NOT NULL REFERENCES nodes, source_epoch bigint NOT NULL, token_hash text NOT NULL UNIQUE,
 state text NOT NULL CHECK(state IN ('PREPARED','ACCEPTED','ACKED','CANCELLED','EXPIRED')),
 expires_at timestamptz NOT NULL, accepted_epoch bigint, operation_id uuid NOT NULL REFERENCES operations
);
CREATE UNIQUE INDEX one_open_transfer ON transfers(player_id) WHERE state IN ('PREPARED','ACCEPTED');
CREATE TABLE mine_nodes (
 channel_id text NOT NULL REFERENCES nodes, node_id text NOT NULL, dimension_id text NOT NULL,
 block_x integer NOT NULL, block_y integer NOT NULL, block_z integer NOT NULL,
 generation bigint NOT NULL CHECK(generation>=0), state text NOT NULL CHECK(state IN ('READY','DEPLETED')),
 respawn_at timestamptz, ore_definition_id text NOT NULL, ore_version integer NOT NULL,
 PRIMARY KEY(channel_id,node_id), UNIQUE(channel_id,dimension_id,block_x,block_y,block_z),
 FOREIGN KEY(ore_definition_id,ore_version) REFERENCES content_definitions
);
CREATE INDEX due_mine_nodes ON mine_nodes(channel_id,respawn_at) WHERE state='DEPLETED';
-- RESERVED is an in-process transient state; generation grant+DEPLETED must commit atomically.
CREATE TABLE parties (
 party_id uuid PRIMARY KEY, leader_id uuid NOT NULL REFERENCES players, version bigint NOT NULL DEFAULT 0,
 state text NOT NULL CHECK(state IN ('OPEN','LOCKED','DISBANDED'))
);
CREATE TABLE party_members (
 party_id uuid NOT NULL REFERENCES parties, player_id uuid NOT NULL REFERENCES players,
 ready boolean NOT NULL DEFAULT false, PRIMARY KEY(party_id,player_id), UNIQUE(player_id)
);
CREATE TABLE instance_slots (
 slot_id uuid PRIMARY KEY, node_id text NOT NULL REFERENCES nodes, template_id text NOT NULL, template_version integer NOT NULL,
 world_key text NOT NULL, state text NOT NULL CHECK(state IN ('WARM','RESERVED','ACTIVE','CLEANING','QUARANTINED')),
 version bigint NOT NULL DEFAULT 0, UNIQUE(node_id,world_key)
);
CREATE TABLE instance_runs (
 run_id uuid PRIMARY KEY, requester_id uuid NOT NULL REFERENCES players, party_id uuid REFERENCES parties,
 slot_id uuid REFERENCES instance_slots, boss_id text NOT NULL, config_version integer NOT NULL,
 state text NOT NULL CHECK(state IN ('REQUESTED','RESERVED','LOADING','READY','ACTIVE','SUCCEEDED','FAILED','RETURNING','CLEANING','CLOSED','ABORTED','QUARANTINED')),
 outcome text CHECK(outcome IN ('SUCCEEDED','FAILED','ABORTED')),
 key_state text NOT NULL CHECK(key_state IN ('RESERVED','CONSUMED','REFUNDED')),
 key_escrow_location_id uuid REFERENCES asset_locations,
 created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz,
 operation_id uuid NOT NULL UNIQUE REFERENCES operations
);
CREATE UNIQUE INDEX occupied_instance_slot ON instance_runs(slot_id)
 WHERE state NOT IN ('CLOSED','ABORTED');
CREATE TABLE run_members (
 run_id uuid NOT NULL REFERENCES instance_runs, player_id uuid NOT NULL REFERENCES players,
 state text NOT NULL CHECK(state IN ('INVITED','READY','ACTIVE','DOWNED','DISCONNECTED','RETURNED')),
 eligible boolean NOT NULL DEFAULT false, reconnect_until timestamptz,
 PRIMARY KEY(run_id,player_id)
);
CREATE TABLE run_rewards (
 run_id uuid NOT NULL REFERENCES instance_runs, player_id uuid NOT NULL REFERENCES players, reward_slot text NOT NULL,
 grant_id uuid NOT NULL UNIQUE REFERENCES reward_grants, PRIMARY KEY(run_id,player_id,reward_slot)
);
CREATE TABLE world_encounters (
 encounter_id uuid PRIMARY KEY, channel_id text NOT NULL REFERENCES nodes, boss_type text NOT NULL,
 schedule_window text NOT NULL, config_version integer NOT NULL,
 state text NOT NULL CHECK(state IN ('SPAWNED','ACTIVE','FINISHED','ABORTED')),
 last_hit_player_id uuid REFERENCES players, outcome jsonb, UNIQUE(channel_id,boss_type,schedule_window)
);
CREATE TABLE encounter_contributions (
 encounter_id uuid NOT NULL REFERENCES world_encounters, player_id uuid NOT NULL REFERENCES players,
 damage_units bigint NOT NULL DEFAULT 0 CHECK(damage_units>=0), support_units bigint NOT NULL DEFAULT 0 CHECK(support_units>=0),
 active_ms bigint NOT NULL DEFAULT 0 CHECK(active_ms>=0), tie_break_at timestamptz,
 PRIMARY KEY(encounter_id,player_id)
);
CREATE TABLE reward_claim_scopes (
 scope_key text NOT NULL, player_id uuid NOT NULL REFERENCES players, grant_id uuid NOT NULL REFERENCES reward_grants,
 PRIMARY KEY(scope_key,player_id)
);
CREATE TABLE workspaces (
 workspace_id uuid PRIMARY KEY, owner_id uuid NOT NULL UNIQUE REFERENCES players, size_tier integer NOT NULL CHECK(size_tier>0),
 layout_version bigint NOT NULL DEFAULT 0, layout jsonb NOT NULL DEFAULT '{}'
);
CREATE TABLE workspace_acl (
 workspace_id uuid NOT NULL REFERENCES workspaces, player_id uuid NOT NULL REFERENCES players,
 permission text NOT NULL CHECK(permission IN ('VISIT','USE_STATION','STORAGE')),
 PRIMARY KEY(workspace_id,player_id,permission)
);
CREATE TABLE processing_jobs (
 job_id uuid PRIMARY KEY, player_id uuid NOT NULL REFERENCES players, workspace_id uuid NOT NULL REFERENCES workspaces,
 recipe_id text NOT NULL, recipe_version integer NOT NULL, operation_id uuid NOT NULL UNIQUE REFERENCES operations,
 input_escrow jsonb NOT NULL, output_spec jsonb NOT NULL,
 state text NOT NULL CHECK(state IN ('RUNNING','READY','CLAIMED','CANCELLED')),
 started_at timestamptz NOT NULL, finishes_at timestamptz NOT NULL, output_grant_id uuid UNIQUE REFERENCES reward_grants,
 CHECK(finishes_at>=started_at), FOREIGN KEY(recipe_id,recipe_version) REFERENCES content_definitions
);
CREATE INDEX jobs_due ON processing_jobs(finishes_at) WHERE state='RUNNING';
CREATE TABLE market_listings (
 listing_id uuid PRIMARY KEY, seller_id uuid NOT NULL REFERENCES players,
 escrow_location_id uuid NOT NULL REFERENCES asset_locations, gross_price bigint NOT NULL CHECK(gross_price>0),
 tax_basis_points integer NOT NULL CHECK(tax_basis_points BETWEEN 0 AND 10000),
 state text NOT NULL CHECK(state IN ('ACTIVE','SOLD','CANCELLED','EXPIRED')),
 buyer_id uuid REFERENCES players, buyer_grant_id uuid REFERENCES reward_grants,
 created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL,
 version bigint NOT NULL DEFAULT 0, CHECK(buyer_id IS NULL OR buyer_id<>seller_id),
 CHECK((state='SOLD')=(buyer_id IS NOT NULL)), CHECK(expires_at>created_at)
);
CREATE UNIQUE INDEX one_active_escrow_listing ON market_listings(escrow_location_id) WHERE state='ACTIVE';
CREATE INDEX market_browse ON market_listings(created_at,listing_id) WHERE state='ACTIVE';
CREATE TABLE outbox_events (
 event_id uuid PRIMARY KEY, operation_id uuid NOT NULL REFERENCES operations, event_type text NOT NULL,
 schema_version integer NOT NULL, aggregate_id text NOT NULL, aggregate_version bigint NOT NULL,
 payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 published_at timestamptz, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0
);
CREATE INDEX outbox_pending ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE TABLE processed_events (
 consumer text NOT NULL, event_id uuid NOT NULL, processed_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(consumer,event_id)
);
CREATE TABLE audit_log (
 audit_id uuid PRIMARY KEY, operation_id uuid REFERENCES operations, actor_principal text NOT NULL,
 action text NOT NULL, target_id text NOT NULL, reason text NOT NULL, before_state jsonb, after_state jsonb,
 created_at timestamptz NOT NULL DEFAULT now()
);
COMMIT;
